#include <SD.h>
#include <Update.h>

void installFromCard() {
  File image = SD.open("/firmware.bin", FILE_READ);
  if (!image || image.size() == 0) {
    Serial.println("Firmware file is missing or empty");
    image.close();
    return;
  }

  const size_t imageSize = image.size();
  if (!verifySignedImage(image, imageSize)) {
    Serial.println("Firmware signature is invalid");
    image.close();
    return;
  }
  if (!Update.begin(imageSize)) {
    Serial.println("Could not start firmware update");
    image.close();
    return;
  }
  const size_t written = Update.writeStream(image);
  if (written == imageSize && Update.end(true)) {
    image.close();
    ESP.restart();
  } else {
    Serial.println("Firmware write failed");
    image.close();
  }
}
